def count_Substrings(s):
    def sum_of_digits(sub):
        return sum(int(char) for char in sub)

    def is_valid_substring(sub):
        return sum_of_digits(sub) == len(sub)

    n = len(s)
    count = 0

    for i in range(n):
        for j in range(i, n):
            sub = s[i:j+1]
            if is_valid_substring(sub):
                count += 1

    return count

# Test cases
